+/** All reports (admin only — RLS lets admins read all), newest first. */
+export async function listReports(): Promise<ReportRow[]> {
+  const supabase = await createClient();
+  const { data, error } = await supabase
+    .from("reports")
+    .select("*")
+    .order("created_at", { ascending: false });
+  if (error) throw error;
+  return data ?? [];
+}
+
+/** Profiles by id (admin reads all via RLS) — to name reporters/targets. */
+export async function getProfilesByIds(
+  ids: string[],
+): Promise<Map<string, ProfileRow>> {
+  const clean = ids.filter(Boolean);
+  if (clean.length === 0) return new Map();
+  const supabase = await createClient();
+  const { data, error } = await supabase
+    .from("profiles")
+    .select("*")
+    .in("id", clean);
+  if (error) throw error;
+  return new Map((data ?? []).map((p) => [p.id, p]));
+}
+
+/** Users for admin management, optionally filtered by name/email search. */
+export async function listUsers(search?: string): Promise<ProfileRow[]> {
+  const supabase = await createClient();
+  let query = supabase.from("profiles").select("*");
+  if (search && search.trim()) {
+    const term = `%${search.trim()}%`;
+    query = query.or(`full_name.ilike.${term},email.ilike.${term}`);
+  }
+  const { data, error } = await query
+    .order("created_at", { ascending: false })
+    .limit(100);
+  if (error) throw error;
+  return data ?? [];
+}
+
